{"path": "react.py", "content": "import itertools

_counter = itertools.count()


class _Cell:
    def __init__(self):
        self._dependents = []
        self._order = next(_counter)  # inputs are always created before dependents
        self._value = None

    @property
    def value(self):
        return self._value


class InputCell(_Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @value.setter
    def value(self, new_value):
        if new_value == self._value:
            return
        self._value = new_value
        # Collect all transitive dependents.
        seen = {}
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if id(cell) not in seen:
                seen[id(cell)] = cell
                stack.extend(cell._dependents)
        ordered = sorted(seen.values(), key=lambda c: c._order)
        old = {id(c): c._value for c in ordered}
        for cell in ordered:
            cell._recompute()
        for cell in ordered:
            if cell._value != old[id(cell)]:
                for cb in list(cell._callbacks):
                    cb(cell._value)


class ComputeCell(_Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = list(inputs)
        self._compute_function = compute_function
        self._callbacks = []
        for cell in self._inputs:
            cell._dependents.append(self)
        self._recompute()

    def _recompute(self):
        self._value = self._compute_function([c.value for c in self._inputs])

    def add_callback(self, callback):
        if callback not in self._callbacks:
            self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)
